-- DUMP DE LA BASE DE DONNEES - METAMIND
-- PostgreSQL 16 - structure et donnees coherentes avec le schema et le dictionnaire.
-- Donnees fictives en domaines .example, sans secret et sans domaine reel.

SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;

DROP TABLE IF EXISTS mouvements_credits CASCADE;
DROP TABLE IF EXISTS packs_credits CASCADE;
DROP TABLE IF EXISTS configurations CASCADE;
DROP TABLE IF EXISTS logs_audit CASCADE;
DROP TABLE IF EXISTS suggestions_metadonnees CASCADE;
DROP TABLE IF EXISTS enrichissements CASCADE;
DROP TABLE IF EXISTS documents_mots_cles CASCADE;
DROP TABLE IF EXISTS documents_auteurs CASCADE;
DROP TABLE IF EXISTS metadonnees CASCADE;
DROP TABLE IF EXISTS documents CASCADE;
DROP TABLE IF EXISTS mots_cles CASCADE;
DROP TABLE IF EXISTS auteurs CASCADE;
DROP TABLE IF EXISTS users CASCADE;
DROP TABLE IF EXISTS types_documents CASCADE;
DROP TABLE IF EXISTS langues CASCADE;
DROP TABLE IF EXISTS institutions CASCADE;

CREATE TABLE institutions (
  id BIGSERIAL PRIMARY KEY,
  nom VARCHAR(255) NOT NULL,
  domaine_email VARCHAR(255) UNIQUE,
  solde_credits INTEGER NOT NULL DEFAULT 0 CHECK (solde_credits >= 0),
  date_creation TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE langues (
  id BIGSERIAL PRIMARY KEY,
  code VARCHAR(5) UNIQUE,
  libelle VARCHAR(50)
);

CREATE TABLE types_documents (
  id BIGSERIAL PRIMARY KEY,
  code VARCHAR(50) UNIQUE,
  libelle VARCHAR(100)
);

CREATE TABLE users (
  id BIGSERIAL PRIMARY KEY,
  email VARCHAR(255) NOT NULL UNIQUE,
  mot_de_passe_hash VARCHAR(255) NOT NULL,
  nom VARCHAR(100),
  prenom VARCHAR(100),
  role VARCHAR(20) NOT NULL CHECK (role IN ('LIBRARIAN','ADMIN')),
  statut VARCHAR(20) NOT NULL CHECK (statut IN ('EN_ATTENTE','ACTIF','DESACTIVE')),
  institution_id BIGINT REFERENCES institutions(id) ON DELETE SET NULL,
  CONSTRAINT ck_users_institution_role CHECK (role <> 'LIBRARIAN' OR institution_id IS NOT NULL),
  CONSTRAINT ck_users_email_format CHECK (position('@' in email) > 1)
);

CREATE TABLE auteurs (
  id BIGSERIAL PRIMARY KEY,
  nom_complet VARCHAR(255) NOT NULL,
  orcid VARCHAR(19)
);

CREATE TABLE mots_cles (
  id BIGSERIAL PRIMARY KEY,
  libelle VARCHAR(150) NOT NULL UNIQUE
);

CREATE TABLE documents (
  id BIGSERIAL PRIMARY KEY,
  nom_fichier VARCHAR(255) NOT NULL,
  chemin_fichier VARCHAR(500),
  taille_fichier BIGINT CHECK (taille_fichier IS NULL OR taille_fichier <= 134217728),
  type_mime VARCHAR(100) CHECK (type_mime IS NULL OR type_mime IN ('PDF','DOCX','TXT')),
  texte_extrait TEXT,
  statut VARCHAR(20) NOT NULL CHECK (statut IN ('EN_ATTENTE','EXTRACTION','A_VALIDER','PUBLIE','SUPPRIME')),
  visibilite VARCHAR(20) NOT NULL CHECK (visibilite IN ('PUBLIC','INSTITUTION')),
  search_vector TSVECTOR,
  institution_id BIGINT REFERENCES institutions(id) ON DELETE CASCADE,
  importe_par BIGINT REFERENCES users(id) ON DELETE SET NULL
);

CREATE TABLE metadonnees (
  id BIGSERIAL PRIMARY KEY,
  document_id BIGINT NOT NULL UNIQUE REFERENCES documents(id) ON DELETE CASCADE,
  titre VARCHAR(500),
  resume TEXT,
  date_publication DATE,
  classification VARCHAR(255),
  langue_id BIGINT REFERENCES langues(id),
  type_document_id BIGINT REFERENCES types_documents(id),
  statut VARCHAR(20) NOT NULL CHECK (statut IN ('EN_ATTENTE','VALIDE','REJETE')),
  date_validation TIMESTAMP,
  validee_par BIGINT REFERENCES users(id) ON DELETE SET NULL,
  date_generation TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE documents_auteurs (
  document_id BIGINT NOT NULL REFERENCES documents(id) ON DELETE CASCADE,
  auteur_id BIGINT NOT NULL REFERENCES auteurs(id) ON DELETE CASCADE,
  ordre_auteur INTEGER CHECK (ordre_auteur > 0),
  PRIMARY KEY (document_id, auteur_id)
);

CREATE TABLE documents_mots_cles (
  document_id BIGINT NOT NULL REFERENCES documents(id) ON DELETE CASCADE,
  mot_cle_id BIGINT NOT NULL REFERENCES mots_cles(id) ON DELETE CASCADE,
  PRIMARY KEY (document_id, mot_cle_id)
);

CREATE TABLE enrichissements (
  id BIGSERIAL PRIMARY KEY,
  document_id BIGINT REFERENCES documents(id) ON DELETE CASCADE,
  lance_par BIGINT REFERENCES users(id) ON DELETE SET NULL,
  statut VARCHAR(20) NOT NULL CHECK (statut IN ('EN_FILE','EN_COURS','TERMINE','ECHEC')),
  modele_llm VARCHAR(100),
  version_prompt VARCHAR(50),
  reponse_brute JSONB,
  message_erreur TEXT,
  date_debut TIMESTAMP,
  date_fin TIMESTAMP,
  CONSTRAINT ck_enrichissements_dates CHECK (date_fin IS NULL OR date_debut IS NULL OR date_fin >= date_debut)
);

CREATE TABLE suggestions_metadonnees (
  id BIGSERIAL PRIMARY KEY,
  enrichissement_id BIGINT REFERENCES enrichissements(id) ON DELETE CASCADE,
  champ VARCHAR(50),
  valeur_suggeree TEXT,
  score_confiance DECIMAL(3,2) CHECK (score_confiance >= 0.00 AND score_confiance <= 1.00),
  decision VARCHAR(20) CHECK (decision IS NULL OR decision IN ('ACCEPTE','MODIFIE','REJETE')),
  valeur_finale TEXT
);

CREATE TABLE logs_audit (
  id BIGSERIAL PRIMARY KEY,
  user_id BIGINT REFERENCES users(id) ON DELETE SET NULL,
  action VARCHAR(50),
  type_entite VARCHAR(50),
  entite_id BIGINT,
  details JSONB,
  adresse_ip VARCHAR(45),
  date_creation TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE configurations (
  cle VARCHAR(100) PRIMARY KEY,
  valeur TEXT,
  modifie_par BIGINT REFERENCES users(id) ON DELETE SET NULL,
  date_modification TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE packs_credits (
  id BIGSERIAL PRIMARY KEY,
  institution_id BIGINT REFERENCES institutions(id) ON DELETE CASCADE,
  quantite INTEGER CHECK (quantite > 0),
  montant_paye DECIMAL(10,2) CHECK (montant_paye >= 0),
  reference_paiement VARCHAR(255),
  statut VARCHAR(20) NOT NULL CHECK (statut IN ('EN_ATTENTE','PAYE','ECHEC')),
  date_achat TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE mouvements_credits (
  id BIGSERIAL PRIMARY KEY,
  institution_id BIGINT REFERENCES institutions(id) ON DELETE CASCADE,
  type VARCHAR(20) NOT NULL CHECK (type IN ('ACHAT','CONSOMMATION')),
  quantite INTEGER NOT NULL,
  enrichissement_id BIGINT REFERENCES enrichissements(id) ON DELETE SET NULL,
  date_mouvement TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT ck_mouvements_signe CHECK ((type = 'ACHAT' AND quantite > 0) OR (type = 'CONSOMMATION' AND quantite < 0))
);

CREATE INDEX idx_users_institution_id ON users(institution_id);
CREATE INDEX idx_documents_institution_id ON documents(institution_id);
CREATE INDEX idx_documents_importe_par ON documents(importe_par);
CREATE INDEX idx_documents_statut_visibilite ON documents(statut, visibilite);
CREATE INDEX idx_documents_search_vector ON documents USING GIN(search_vector);
CREATE INDEX idx_metadonnees_langue_id ON metadonnees(langue_id);
CREATE INDEX idx_metadonnees_type_document_id ON metadonnees(type_document_id);
CREATE INDEX idx_documents_auteurs_auteur_id ON documents_auteurs(auteur_id);
CREATE INDEX idx_documents_mots_cles_mot_cle_id ON documents_mots_cles(mot_cle_id);
CREATE INDEX idx_enrichissements_document_id ON enrichissements(document_id);
CREATE INDEX idx_suggestions_enrichissement_id ON suggestions_metadonnees(enrichissement_id);
CREATE INDEX idx_logs_audit_user_date ON logs_audit(user_id, date_creation);
CREATE INDEX idx_packs_credits_institution_id ON packs_credits(institution_id);
CREATE INDEX idx_mouvements_credits_institution_date ON mouvements_credits(institution_id, date_mouvement);

















