SELECT setval(pg_get_serial_sequence('documents','id'), 100);
SELECT setval(pg_get_serial_sequence('metadonnees','id'), 100);
SELECT setval(pg_get_serial_sequence('enrichissements','id'), 100);
SELECT setval(pg_get_serial_sequence('suggestions_metadonnees','id'), 300);
SELECT setval(pg_get_serial_sequence('packs_credits','id'), 100);
SELECT setval(pg_get_serial_sequence('mouvements_credits','id'), 200);
SELECT setval(pg_get_serial_sequence('logs_audit','id'), 100);
